1	import { Injectable, Logger } from '@nestjs/common';
2	import * as crypto from 'crypto';
3	import { SupabaseService } from '../supabase/supabase.service';
4	import { GeocodingService } from './geocoding.service';
5	
6	interface Coordenadas {
7	  lat: number;
8	  lng: number;
9	}
10	
11	function haversineKm(a: Coordenadas, b: Coordenadas): number {
12	  const R = 6371;
13	  const dLat = ((b.lat - a.lat) * Math.PI) / 180;
14	  const dLng = ((b.lng - a.lng) * Math.PI) / 180;
15	  const s =
16	    Math.sin(dLat / 2) ** 2 +
17	    Math.cos((a.lat * Math.PI) / 180) * Math.cos((b.lat * Math.PI) / 180) * Math.sin(dLng / 2) ** 2;
18	  return R * 2 * Math.atan2(Math.sqrt(s), Math.sqrt(1 - s));
19	}
20	
21	interface PedidoParaComissao {
22	  id: number;
23	  restaurant_id: number;
24	  total: number;
25	  frete_cobrado: number;
26	  customer_id: number | null;
27	}
28	
29	@Injectable()
30	export class ComissaoService {
31	  private readonly logger = new Logger(ComissaoService.name);
32	
33	  constructor(
34	    private supabase: SupabaseService,
35	    private geocoding: GeocodingService,
36	  ) {}
37	
38	  // Idempotente via UNIQUE(pedido_id) — chamado sempre que um pedido é marcado como entregue.
39	  async registrarComissaoEntrega(pedido: PedidoParaComissao, motoboyId: number) {
40	    const { data: existente } = await this.supabase.client
41	      .from('motoboy_comissoes')
42	      .select('id')
43	      .eq('pedido_id', pedido.id)
44	      .maybeSingle();
45	    if (existente) return existente;
46	
47	    const { data: restaurant } = await this.supabase.client
48	      .from('restaurants')
49	      .select(
50	        'motoboy_comissao_tipo, motoboy_comissao_valor_fixo, motoboy_comissao_percentual, motoboy_comissao_valor_km, motoboy_comissao_km_fallback, lat, lng',
51	      )
52	      .eq('id', pedido.restaurant_id)
53	      .maybeSingle();
54	    if (!restaurant) return null;
55	
56	    // O motoboy sempre recebe o frete cobrado do cliente — o tipo configurado
57	    // (fixo/percentual/km) é um ADICIONAL somado em cima disso, não substituto.
58	    const freteRepassado = Number(pedido.frete_cobrado ?? 0);
59	    let tipo = restaurant.motoboy_comissao_tipo as string;
60	    let adicional = 0;
61	    let distanciaKm: number | null = null;
62	    let valorPorKm: number | null = null;
63	    let percentual: number | null = null;
64	    let valorBase = 0;
65	
66	    if (tipo === 'fixo') {
67	      valorBase = Number(restaurant.motoboy_comissao_valor_fixo);
68	      adicional = valorBase;
69	    } else if (tipo === 'percentual') {
70	      percentual = Number(restaurant.motoboy_comissao_percentual);
71	      valorBase = freteRepassado;
72	      adicional = freteRepassado * (percentual / 100);
73	    } else if (tipo === 'km') {
74	      const distancia = await this.calcularDistanciaPedido(pedido.customer_id, restaurant.lat, restaurant.lng);
75	      if (distancia !== null) {
76	        distanciaKm = parseFloat(distancia.toFixed(2));
77	        valorPorKm = Number(restaurant.motoboy_comissao_valor_km);
78	        adicional = distancia * valorPorKm;
79	      } else {
80	        tipo = 'km_fallback';
81	        valorBase = Number(restaurant.motoboy_comissao_km_fallback);
82	        adicional = valorBase;
83	      }
84	    }
85	
86	    const comissaoValor = freteRepassado + adicional;
87	
88	    const { data, error } = await this.supabase.client
89	      .from('motoboy_comissoes')
90	      .insert({
91	        motoboy_id: motoboyId,
92	        restaurant_id: pedido.restaurant_id,
93	        pedido_id: pedido.id,
94	        tipo,
95	        valor_base: valorBase,
96	        frete_repassado: parseFloat(freteRepassado.toFixed(2)),
97	        percentual,
98	        distancia_km: distanciaKm,
99	        valor_por_km: valorPorKm,
100	        comissao_valor: parseFloat(comissaoValor.toFixed(2)),
101	      })
102	      .select()
103	      .single();
104	
105	    if (error) {
106	      // Corrida (dupla chamada) esbarra no UNIQUE(pedido_id) — não é um erro fatal aqui.
107	      this.logger.warn(`Falha ao registrar comissão do pedido ${pedido.id}: ${error.message}`);
108	      return null;
109	    }
110	    return data;
