import React, { useState } from 'react';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import Input from '../../../components/ui/Input';

const AddressSelector = ({ 
  selectedAddress, 
  onAddressChange, 
  addresses = [],
  onAddNewAddress,
  primaryColor = '#2563EB' 
}) => {
  const [showAddForm, setShowAddForm] = useState(false);
  const [newAddress, setNewAddress] = useState({
    street: '',
    number: '',
    complement: '',
    neighborhood: '',
    city: '',
    zipCode: '',
    reference: ''
  });

  const handleAddAddress = () => {
    if (newAddress?.street && newAddress?.number && newAddress?.neighborhood) {
      const addressData = {
        id: Date.now(),
        ...newAddress,
        fullAddress: `${newAddress?.street}, ${newAddress?.number}${newAddress?.complement ? `, ${newAddress?.complement}` : ''}, ${newAddress?.neighborhood}, ${newAddress?.city}`
      };

      onAddNewAddress(addressData);
      setShowAddForm(false);
      setNewAddress({
        street: '',
        number: '',
        complement: '',
        neighborhood: '',
        city: '',
        zipCode: '',
        reference: ''
      });
    }
  };

  const handleInputChange = (field, value) => {
    setNewAddress(prev => ({
      ...prev,
      [field]: value
    }));
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-semibold text-foreground">Endereço de Entrega</h3>
        <Button
          variant="outline"
          size="sm"
          onClick={() => setShowAddForm(!showAddForm)}
